/* CSS PART 1 OF 2 */

/* ---------- Design tokens ---------- */
:root {
  color-scheme: light;
  --color-forest: #203d30;
  --color-forest-deep: #172c23;
  --color-sage: #819477;
  --color-moss: #a7ad83;
  --color-cream: #f5f2e9;
  --color-paper: #fffdf8;
  --color-earth: #a36f4d;
  --color-ink: #27332b;
  --color-muted: #6d756b;
  --color-line: #deded2;
  --color-white: #ffffff;

  --font-display: Georgia, "Times New Roman", serif;
  --font-body: "Avenir Next", Avenir, "Segoe UI", sans-serif;

  --container: 1200px;
  --gutter: clamp(22px, 6vw, 88px);
  --section-space: clamp(76px, 10vw, 132px);

  --radius-sm: 5px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow-soft: 0 14px 45px rgba(30, 49, 36, 0.09);

  --transition: 220ms ease;
}

/* ---------- Reset and foundations ---------- */
* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  background: var(--color-paper);
  color: var(--color-ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--color-earth);
  outline-offset: 4px;
}

::selection {
  background: var(--color-sage);
  color: var(--color-forest-deep);
}

/* ---------- Shared typography ---------- */
h1,
h2,
h3,
p {
  margin-top: 0;
}

h1,
h2,
h3 {
  color: var(--color-forest);
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: -0.035em;
  line-height: 1.12;
}

h1 {
  font-size: clamp(3.2rem, 7.6vw, 6.8rem);
}

h2 {
  margin-bottom: 24px;
  font-size: clamp(2.5rem, 5vw, 4.35rem);
}

h3 {
  font-size: clamp(1.45rem, 2.5vw, 2rem);
}

p {
  color: var(--color-muted);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
  color: var(--color-sage);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.19em;
  line-height: 1.5;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 30px;
  height: 1px;
  background: currentColor;
  content: "";
}

.section-intro {
  max-width: 660px;
  margin-bottom: 52px;
}

.section-intro p {
  max-width: 560px;
  font-size: 1.06rem;
}

.text-accent {
  color: var(--color-earth);
}

.container {
  width: min(100% - var(--gutter) * 2, var(--container));
  margin-inline: auto;
}

.section {
  padding-block: var(--section-space);
}

.section--cream {
  background: var(--color-cream);
}

.section--forest {
  background: var(--color-forest);
  color: var(--color-white);
}

.section--forest h2,
.section--forest h3 {
  color: var(--color-white);
}

.section--forest p {
  color: rgba(255, 255, 255, 0.76);
}

/* ---------- Header and navigation ---------- */
.site-header {
  position: relative;
  z-index: 20;
  width: 100%;
  background: var(--color-paper);
  border-bottom: 1px solid rgba(32, 61, 48, 0.09);
}

.header-inner {
  display: flex;
  min-height: 88px;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 13px;
  flex-shrink: 0;
  color: var(--color-forest);
}

.brand img {
  width: 54px;
  height: 54px;
  object-fit: contain;
}

.brand-name {
  display: flex;
  flex-direction: column;
  font-family: var(--font-display);
  font-size: 1.3rem;
  line-height: 1.05;
}

.brand-name small {
  margin-top: 6px;
  color: var(--color-muted);
  font-family: var(--font-body);
  font-size: 0.59rem;
  font-weight: 700;
  letter-spacing: 0.17em;
  text-transform: uppercase;
}

.main-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(20px, 3vw, 38px);
}

.main-nav a:not(.button) {
  position: relative;
  padding-block: 9px;
  color: var(--color-ink);
  font-size: 0.82rem;
  font-weight: 600;
  transition: color var(--transition);
}

.main-nav a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: 2px;
  left: 0;
  height: 1px;
  background: var(--color-earth);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.main-nav a:not(.button):hover {
  color: var(--color-earth);
}

.main-nav a:not(.button):hover::after {
  transform: scaleX(1);
}

/* ---------- Buttons ---------- */
.button {
  display: inline-flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px 25px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: var(--color-forest);
  color: var(--color-white);
  cursor: pointer;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-align: center;
  text-transform: uppercase;
  transition:
    background var(--transition),
    color var(--transition),
    border-color var(--transition),
    transform var(--transition);
}

.button:hover {
  background: var(--color-forest-deep);
  transform: translateY(-2px);
}

.button--light {
  border-color: var(--color-white);
  background: var(--color-white);
  color: var(--color-forest);
}

.button--light:hover {
  border-color: var(--color-white);
  background: transparent;
  color: var(--color-white);
}

.button--outline {
  border-color: rgba(32, 61, 48, 0.35);
  background: transparent;
  color: var(--color-forest);
}

.button--outline:hover {
  background: var(--color-forest);
  color: var(--color-white);
}

.button-arrow {
  font-size: 1.15rem;
  line-height: 1;
  transition: transform var(--transition);
}

.button:hover .button-arrow {
  transform: translateX(4px);
}

/* ---------- Full-bleed hero ---------- */
.hero {
  position: relative;
  display: flex;
  min-height: min(780px, calc(100svh - 88px));
  align-items: center;
  overflow: hidden;
  background: var(--color-forest-deep);
  color: var(--color-white);
}

.hero-image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 52%;
}

.hero::before {
  position: absolute;
  z-index: 1;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(19, 39, 29, 0.88) 0%,
      rgba(19, 39, 29, 0.67) 43%,
      rgba(19, 39, 29, 0.17) 100%
    ),
    linear-gradient(
      0deg,
      rgba(19, 39, 29, 0.32),
      transparent 48%
    );
  content: "";
}

.hero-content {
  position: relative;
  z-index: 2;
  width: min(100% - var(--gutter) * 2, var(--container));
  margin: 0 auto;
  padding-block: 100px;
}

.hero .eyebrow {
  color: #d5d9b9;
}

.hero h1 {
  max-width: 850px;
  margin-bottom: 27px;
  color: var(--color-white);
}

.hero h1 em {
  color: #d4d6b4;
  font-weight: 400;
}

.hero-description {
  max-width: 520px;
  margin-bottom: 36px;
  color: rgba(255, 255, 255, 0.88);
  font-size: clamp(1rem, 1.5vw, 1.15rem);
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.hero-note {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-top: 48px;
  color: rgba(255, 255, 255, 0.83);
  font-size: 0.76rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.hero-note::before {
  width: 34px;
  height: 1px;
  background: #d4d6b4;
  content: "";
}

/* ---------- Introduction ---------- */
.intro-section {
  position: relative;
  overflow: hidden;
  padding-block: var(--section-space);
}

.intro-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: center;
  gap: clamp(48px, 9vw, 130px);
}

.intro-heading {
  max-width: 460px;
}

.intro-heading h2 {
  margin-bottom: 0;
}

.intro-copy {
  max-width: 570px;
}

.intro-copy p {
  font-size: 1.05rem;
  line-height: 1.9;
}

.intro-copy .button {
  margin-top: 17px;
}

/* ---------- Services ---------- */
.services-section {
  background: var(--color-cream);
  padding-block: var(--section-space);
}

.services-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 35px;
  margin-bottom: 55px;
}

.services-heading .section-intro {
  margin-bottom: 0;
}

.services-heading > p {
  max-width: 310px;
  margin-bottom: 9px;
}

.services-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-top: 1px solid var(--color-line);
  border-left: 1px solid var(--color-line);
}

.service-item {
  min-height: 225px;
  padding: 35px;
  border-right: 1px solid var(--color-line);
  border-bottom: 1px solid var(--color-line);
  background: rgba(255, 253, 248, 0.5);
  transition:
    background var(--transition),
    transform var(--transition);
}

.service-item:hover {
  position: relative;
  z-index: 1;
  background: var(--color-paper);
  transform: translateY(-3px);
}

.service-number {
  display: block;
  margin-bottom: 25px;
  color: var(--color-earth);
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-style: italic;
}

.service-item h3 {
  margin-bottom: 12px;
}

.service-item p {
  margin-bottom: 0;
  font-size: 0.92rem;
  line-height: 1.75;
}

/* ---------- Family-owned difference ---------- */
.difference-section {
  padding-block: var(--section-space);
  background: var(--color-forest);
  color: var(--color-white);
}

.difference-layout {
  display: grid;
  grid-template-columns: 1fr 0.85fr;
  align-items: center;
  gap: clamp(50px, 9vw, 120px);
}

.difference-content {
  max-width: 620px;
}

.difference-content h2 {
  color: var(--color-white);
}

.difference-content p {
  max-width: 540px;
  font-size: 1.03rem;
  line-height: 1.9;
}

.difference-points {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0 30px;
  margin-top: 38px;
}

.difference-point {
  padding-block: 18px;
  border-top: 1px solid rgba(255, 255, 255, 0.22);
  color: rgba(255, 255, 255, 0.94);
  font-family: var(--font-display);
  font-size: 1.12rem;
}

.difference-point::before {
  margin-right: 11px;
  color: #c5cba4;
  content: "↗";
  font-family: var(--font-body);
  font-size: 0.85rem;
}

.difference-aside {
  padding: clamp(30px, 5vw, 54px);
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: var(--radius-md);
  background: rgba(255, 255, 255, 0.045);
}

.difference-aside h3 {
  margin-bottom: 20px;
  color: #e2e2c9;
}

.difference-aside p {
  margin-bottom: 0;
}

/* ---------- Local sourcing / working approach ---------- */
.approach-section {
  padding-block: var(--section-space);
}

.approach-layout {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: center;
  gap: clamp(48px, 9vw, 115px);
}

.approach-heading {
  max-width: 460px;
}

.approach-copy {
  max-width: 580px;
}

.approach-copy p {
  font-size: 1.04rem;
  line-height: 1.9;
}

.approach-highlight {
  margin-top: 30px;
  padding: 22px 25px;
  border-left: 3px solid var(--color-sage);
  background: var(--color-cream);
  color: var(--color-forest);
  font-family: var(--font-display);
  font-size: 1.2rem;
  line-height: 1.55;
}

/* ---------- Reduced-motion preference ---------- */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
