/* CSS PART 2 OF 2 */

/* ---------- Contact and conversion ---------- */
.contact-section {
  padding-block: var(--section-space);
  background: var(--color-cream);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: start;
  gap: clamp(45px, 8vw, 110px);
}

.contact-content {
  max-width: 470px;
}

.contact-content h2 {
  margin-bottom: 24px;
}

.contact-content > p {
  font-size: 1.05rem;
  line-height: 1.85;
}

.contact-details {
  margin-top: 38px;
  padding-top: 25px;
  border-top: 1px solid var(--color-line);
}

.contact-details p {
  margin-bottom: 8px;
  color: var(--color-forest);
  font-weight: 600;
}

.contact-form {
  display: grid;
  gap: 21px;
  padding: clamp(25px, 5vw, 48px);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-md);
  background: var(--color-paper);
  box-shadow: var(--shadow-soft);
}

.form-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.form-field {
  display: grid;
  gap: 8px;
}

.form-field label {
  color: var(--color-forest);
  font-size: 0.78rem;
  font-weight: 700;
}

.form-field input,
.form-field textarea,
.form-field select {
  width: 100%;
  min-height: 52px;
  padding: 13px 15px;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-sm);
  background: var(--color-white);
  color: var(--color-ink);
  transition: border-color var(--transition);
}

.form-field textarea {
  min-height: 145px;
  resize: vertical;
}

.form-field input:hover,
.form-field textarea:hover,
.form-field select:hover {
  border-color: var(--color-sage);
}

.form-field input:focus,
.form-field textarea:focus,
.form-field select:focus {
  border-color: var(--color-forest);
  outline: 2px solid var(--color-sage);
  outline-offset: 2px;
}

.contact-form .button {
  justify-self: start;
  min-width: 190px;
}

.form-note {
  margin: 0;
  color: var(--color-muted);
  font-size: 0.78rem;
}

/* ---------- Footer ---------- */
.site-footer {
  padding: 55px 0 25px;
  background: var(--color-forest-deep);
  color: var(--color-white);
}

.footer-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 35px;
  padding-bottom: 40px;
}

.footer-brand {
  color: var(--color-white);
}

.footer-brand .brand-name small {
  color: rgba(255, 255, 255, 0.65);
}

.footer-copy {
  max-width: 350px;
  margin: 0;
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.9rem;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding-top: 23px;
  border-top: 1px solid rgba(255, 255, 255, 0.18);
}

.footer-bottom p {
  margin: 0;
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.75rem;
}

/* ---------- Accessible mobile navigation ---------- */
.menu-toggle {
  display: none;
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--color-forest);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

@media (max-width: 900px) {
  :root {
    --section-space: 85px;
  }

  .header-inner {
    min-height: 78px;
  }

  .menu-toggle {
    display: flex;
  }

  .main-nav {
    position: absolute;
    top: 100%;
    right: 0;
    left: 0;
    display: none;
    max-height: calc(100svh - 78px);
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    gap: 0;
    overflow-y: auto;
    padding: 15px var(--gutter) 25px;
    border-bottom: 1px solid var(--color-line);
    background: var(--color-paper);
    box-shadow: var(--shadow-soft);
  }

  .main-nav.is-open {
    display: flex;
  }

  .main-nav a:not(.button) {
    display: block;
    width: 100%;
    padding: 14px 0;
    overflow-wrap: anywhere;
    border-bottom: 1px solid var(--color-line);
  }

  .main-nav .button {
    width: 100%;
    margin-top: 17px;
  }

  .hero {
    min-height: 680px;
  }

  .hero::before {
    background: linear-gradient(
      90deg,
      rgba(19, 39, 29, 0.84),
      rgba(19, 39, 29, 0.43)
    );
  }

  .intro-layout,
  .difference-layout,
  .approach-layout,
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .intro-heading,
  .approach-heading,
  .contact-content {
    max-width: 650px;
  }

  .difference-aside {
    max-width: 650px;
  }

  .services-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .services-heading {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 600px) {
  :root {
    --gutter: 22px;
    --section-space: 68px;
  }

  body {
    font-size: 15px;
  }

  .header-inner {
    min-height: 72px;
  }

  .brand img {
    width: 45px;
    height: 45px;
  }

  .brand-name {
    font-size: 1.12rem;
  }

  .brand-name small {
    font-size: 0.53rem;
  }

  .main-nav {
    max-height: calc(100svh - 72px);
  }

  h1 {
    font-size: clamp(3rem, 13vw, 4.6rem);
  }

  h2 {
    font-size: clamp(2.35rem, 10vw, 3.3rem);
  }

  .hero {
    min-height: 690px;
    min-height: min(760px, calc(100svh - 72px));
    align-items: flex-end;
  }

  .hero-image {
    object-position: 58% center;
  }

  .hero::before {
    background:
      linear-gradient(
        0deg,
        rgba(19, 39, 29, 0.94) 0%,
        rgba(19, 39, 29, 0.76) 48%,
        rgba(19, 39, 29, 0.22) 100%
      );
  }

  .hero-content {
    padding-top: 100px;
    padding-bottom: 65px;
  }

  .hero h1 {
    max-width: 100%;
    margin-bottom: 20px;
  }

  .hero-description {
    font-size: 0.98rem;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-note {
    margin-top: 30px;
    font-size: 0.67rem;
  }

  .section-intro {
    margin-bottom: 35px;
  }

  .intro-layout,
  .difference-layout,
  .approach-layout,
  .contact-layout {
    gap: 27px;
  }

  .services-grid {
    grid-template-columns: 1fr;
  }

  .service-item {
    min-height: auto;
    padding: 26px;
  }

  .service-number {
    margin-bottom: 14px;
  }

  .difference-points {
    grid-template-columns: 1fr;
  }

  .difference-aside {
    padding: 27px;
  }

  .approach-highlight {
    padding: 19px;
    font-size: 1.08rem;
  }

  .contact-form {
    gap: 17px;
    padding: 23px 19px;
  }

  .form-row {
    grid-template-columns: 1fr;
    gap: 17px;
  }

  .contact-form .button {
    width: 100%;
  }

  .footer-main,
  .footer-bottom {
    align-items: flex-start;
    flex-direction: column;
  }

  .footer-main {
    gap: 22px;
    padding-bottom: 28px;
  }

  .footer-bottom {
    gap: 10px;
  }
}

@media (max-width: 360px) {
  :root {
    --gutter: 17px;
  }

  .brand {
    gap: 8px;
  }

  .brand-name {
    font-size: 1rem;
  }

  .hero h1 {
    font-size: 2.8rem;
  }

  .button {
    padding-inline: 17px;
  }
}

/* ---------- Visible keyboard focus ---------- */
:focus-visible {
  outline: 3px solid var(--color-earth);
  outline-offset: 4px;
}

.main-nav a:focus-visible,
.button:focus-visible,
.menu-toggle:focus-visible {
  outline-color: var(--color-earth);
  outline-offset: 4px;
}

/* ---------- Reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
